alter table public.orders add column if not exists exchange_rate numeric(14,6);
alter table public.orders add column if not exists discount numeric(14,2) not null default 0 check (discount >= 0);
alter table public.products add column if not exists price_reference text not null default 'HTG' check (price_reference in ('HTG','USD'));
alter table public.products add column if not exists price_mode text not null default 'manual' check (price_mode in ('manual','automatic'));
alter table public.products add column if not exists cost_price numeric(14,2) check (cost_price is null or cost_price >= 0);
alter table public.shipping_zones add column if not exists delivery_type text not null default 'standard';
alter table public.shipping_zones add column if not exists free_threshold numeric(14,2);
alter table public.shipping_zones add column if not exists extra_fee numeric(14,2) not null default 0 check (extra_fee >= 0);
alter table public.notifications add column if not exists provider_message_id text;
alter table public.notifications add column if not exists template_name text;
alter table public.notifications add column if not exists idempotency_key text;
create unique index if not exists notifications_idempotency_unique on public.notifications(idempotency_key) where idempotency_key is not null;
create table if not exists public.product_images (id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,storage_path text not null,position integer not null default 0,created_at timestamptz not null default now(),unique(product_id,storage_path));
alter table public.product_images enable row level security;
create policy "public product images" on public.product_images for select to anon,authenticated using (true);
create policy "admin product images insert" on public.product_images for insert to authenticated with check (public.has_permission('products.write'));
create policy "admin product images update" on public.product_images for update to authenticated using (public.has_permission('products.write')) with check (public.has_permission('products.write'));
create policy "admin product images delete" on public.product_images for delete to authenticated using (public.has_permission('products.write'));
insert into public.store_settings(key,value) values ('commerce','{"exchange_rate":135,"currency_decimals":2,"rounding":"half_up","default_low_stock":3}'::jsonb),('brand','{"logo_path":"","tagline":"Plus qu’un produit, une lumière dans votre quotidien."}'::jsonb) on conflict (key) do nothing;
create policy "staff settings read" on public.store_settings for select to authenticated using (public.is_staff());
create policy "staff exchange rates read" on public.exchange_rates for select to authenticated using (public.is_staff());
create policy "admin exchange rates insert" on public.exchange_rates for insert to authenticated with check (public.has_permission('settings.write'));
create policy "admin shipping insert" on public.shipping_zones for insert to authenticated with check (public.has_permission('orders.write'));
create policy "admin shipping update" on public.shipping_zones for update to authenticated using (public.has_permission('orders.write')) with check (public.has_permission('orders.write'));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('product-images','product-images',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict (id) do nothing;
create policy "public product media read" on storage.objects for select to anon,authenticated using (bucket_id='product-images');
create policy "admin product media insert" on storage.objects for insert to authenticated with check (bucket_id='product-images' and public.has_permission('products.write'));
create policy "admin product media update" on storage.objects for update to authenticated using (bucket_id='product-images' and public.has_permission('products.write')) with check (bucket_id='product-images' and public.has_permission('products.write'));
create policy "admin product media delete" on storage.objects for delete to authenticated using (bucket_id='product-images' and public.has_permission('products.write'));
create or replace function public.admin_set_exchange_rate(p_rate numeric,p_note text default '') returns void language plpgsql security definer set search_path='public' as $$ begin if not public.has_permission('settings.write') then raise exception 'PERMISSION_DENIED'; end if; if p_rate<=0 or p_rate>100000 then raise exception 'INVALID_RATE'; end if; insert into public.exchange_rates(base_currency,quote_currency,rate,created_by) values('USD','HTG',p_rate,auth.uid()); update public.store_settings set value=jsonb_set(value,'{exchange_rate}',to_jsonb(p_rate)),updated_at=now() where key='commerce'; insert into public.audit_logs(actor_id,action,resource,metadata) values(auth.uid(),'exchange_rate.changed','store_settings',jsonb_build_object('rate',p_rate,'note',left(p_note,500))); end $$;
create or replace function public.admin_update_payment_status(p_order_id uuid,p_status payment_status,p_reference text default '') returns void language plpgsql security definer set search_path='public' as $$ declare v_old payment_status; begin if not public.has_permission('payment.write') then raise exception 'PERMISSION_DENIED'; end if; select payment_status into v_old from public.orders where id=p_order_id for update; if not found then raise exception 'ORDER_NOT_FOUND'; end if; update public.orders set payment_status=p_status,updated_at=now() where id=p_order_id; insert into public.payment_status_history(order_id,actor_id,from_status,to_status,reference) values(p_order_id,auth.uid(),v_old,p_status,left(p_reference,200)); insert into public.audit_logs(actor_id,action,resource,resource_id,metadata) values(auth.uid(),'order.payment_changed','orders',p_order_id::text,jsonb_build_object('from',v_old,'to',p_status)); end $$;
create or replace function public.admin_set_staff_role(p_user_id uuid,p_role text) returns void language plpgsql security definer set search_path='public' as $$ begin if not public.has_permission('staff.write') then raise exception 'PERMISSION_DENIED'; end if; if p_user_id=auth.uid() then raise exception 'CANNOT_CHANGE_OWN_ROLE'; end if; if p_role not in ('super_admin','manager','catalog_manager','order_manager','inventory_manager','viewer') then raise exception 'INVALID_ROLE'; end if; delete from public.user_roles where user_id=p_user_id; insert into public.user_roles(user_id,role) values(p_user_id,p_role); insert into public.audit_logs(actor_id,action,resource,resource_id,metadata) values(auth.uid(),'staff.role_changed','profiles',p_user_id::text,jsonb_build_object('role',p_role)); end $$;
create or replace function public.admin_retry_notification(p_notification_id uuid) returns void language plpgsql security definer set search_path='public' as $$ begin if not public.has_permission('orders.write') then raise exception 'PERMISSION_DENIED'; end if; update public.notifications set status='pending',next_attempt_at=now(),error_code=null where id=p_notification_id and status='failed'; if not found then raise exception 'NOTIFICATION_NOT_RETRYABLE'; end if; end $$;
grant execute on function public.admin_set_exchange_rate(numeric,text) to authenticated;
grant execute on function public.admin_update_payment_status(uuid,payment_status,text) to authenticated;
grant execute on function public.admin_set_staff_role(uuid,text) to authenticated;
grant execute on function public.admin_retry_notification(uuid) to authenticated;
